    if (parts[0] === 'task') {
      if (parts.length !== 3) {
        throw new Error(`error: line ${lineNum}: expected task <name> <cost>`);
      }

      const name = parts[1];
      const costStr = parts[2];

      // Validate name
      if (!/^[A-Za-z0-9_.\-]+$/.test(name)) {
        throw new Error(`error: line ${lineNum}: invalid task name ${name}`);
      }

      // Validate cost
      if (!/^\d+$/.test(costStr)) {
        throw new Error(`error: line ${lineNum}: cost must be a non-negative integer`);
      }

      const cost = parseInt(costStr, 10);

      // Check for duplicate
      if (tasks.has(name)) {
        throw new Error(`error: line ${lineNum}: task ${name} is declared twice`);
      }

      tasks.set(name, cost);
    } else if (parts[0] === 'dep') {
      if (parts.length < 2) {
        throw new Error(`error: line ${lineNum}: expected dep <name> <dependency>...`);
      }

      const name = parts[0];
      const dependencies = parts.slice(1);

      if (!deps.has(name)) {
        deps.set(name, new Set());
      }

      for (const dep of dependencies) {
        deps.get(name).add(dep);
      }
    } else {
      throw new Error(`error: line ${lineNum}: unknown directive ${parts[0]}`);
    }
  }

  // Validate that all dependencies exist
  const allNames = new Set(tasks.keys());

  // Check dependencies in order they appear
  const allDeps = new Set();
  for (const [_, taskDeps] of deps) {
    for (const dep of taskDeps) {
      allDeps.add(dep);
    }
  }

  for (const dep of Array.from(allDeps).sort()) {
    if (!allNames.has(dep)) {
      throw new Error(`error: unknown task ${dep}`);
    }
  }

  return {
    tasks,
    deps
  };
}

function detectCycle(graph) {
  const visited = new Set();
  const recStack = new Set();
  const stack = [];

  // Process tasks in ascending order
  const sortedTasks = Array.from(graph.tasks.keys()).sort();

  for (const task of sortedTasks) {
    if (!visited.has(task)) {
      const cycle = dfs(task, visited, recStack, stack, graph);
      if (cycle) return cycle;
    }
  }

  return null;

  function dfs(node, visited, recStack, stack, graph) {
    visited.add(node);
    recStack.add(node);
    stack.push(node);

    const dependencies = graph.deps.get(node) || new Set();
    const sortedDeps = Array.from(dependencies).sort();

    for (const dep of sortedDeps) {
      if (!visited.has(dep)) {
        const cycle = dfs(dep, visited, recStack, stack, graph);
        if (cycle) return cycle;
      } else if (recStack.has(dep)) {
        // Found a cycle
        const idx = stack.indexOf(dep);
        const cycle = stack.slice(idx).concat([dep]);
        return cycle;
      }
    }

    recStack.delete(node);
    stack.pop();
    return null;
  }
}

function computeDepth(task, graph, memo) {
  if (memo.has(task)) return memo.get(task);

  const dependencies = graph.deps.get(task) || new Set();

  if (dependencies.size === 0) {
    memo.set(task, 0);
    return 0;
  }

  let maxDepth = 0;
  for (const dep of dependencies) {
    const depDepth = computeDepth(dep, graph, memo);
    maxDepth = Math.max(maxDepth, depDepth);
  }

  const depth = maxDepth + 1;
  memo.set(task, depth);
  return depth;
}

function computeStart(task, graph, memo) {
  if (memo.has(task)) return memo.get(task);

  const dependencies = graph.deps.get(task) || new Set();

  if (dependencies.size === 0) {
    memo.set(task, 0);
    return 0;
  }

  let maxFinish = 0;
  for (const dep of dependencies) {
    const depStart = computeStart(dep, graph, memo);
    const depCost = graph.tasks.get(dep);
    const depFinish = depStart + depCost;
    maxFinish = Math.max(maxFinish, depFinish);
  }

  memo.set(task, maxFinish);
  return maxFinish;
}

function processWaves(graph) {
  if (graph.tasks.size === 0) {
    process.stdout.write('total 0\n');
    return;
  }

  const waves = new Map();
  const depthMemo = new Map();

  // Compute depth for each task
  for (const task of graph.tasks.keys()) {
    const depth = computeDepth(task, graph, depthMemo);

    if (!waves.has(depth)) {
      waves.set(depth, []);
    }
    waves.get(depth).push(task);
  }

  // Sort and print
  const maxDepth = Math.max(...Array.from(depthMemo.values()));

  for (let i = 0; i <= maxDepth; i++) {
    const waveTasks = waves.get(i) || [];
    waveTasks.sort();
    process.stdout.write(`wave ${i}: ${waveTasks.join(' ')}\n`);
  }

  // Compute makespan
  let makespan = 0;
  const startMemo = new Map();

  for (const task of graph.tasks.keys()) {
    const start = computeStart(task, graph, startMemo);
    const finish = start + graph.tasks.get(task);
    makespan = Math.max(makespan, finish);
  }

  process.stdout.write(`total ${makespan}\n`);
}

function processExplain(graph) {
  const tasks = Array.from(graph.tasks.keys()).sort();
  const startMemo = new Map();
  const depthMemo = new Map();

  let makespan = 0;

  for (const task of tasks) {
    const start = computeStart(task, graph, startMemo);
    const finish = start + graph.tasks.get(task);
    const depth = computeDepth(task, graph, depthMemo);

    process.stdout.write(`${task} start=${start} finish=${finish} depth=${depth}\n`);
    makespan = Math.max(makespan, finish);
  }

  process.stdout.write(`total ${makespan}\n`);
}

function computePriority(task, graph, memo) {
  if (memo.has(task)) return memo.get(task);

  const cost = graph.tasks.get(task);

  // Find the longest chain from this task to any leaf
  let maxChainFromDependents = 0;

  for (const otherTask of graph.tasks.keys()) {
    const dependencies = graph.deps.get(otherTask) || new Set();
    if (dependencies.has(task)) {
      const chainFromDependent = computePriority(otherTask, graph, memo);
      maxChainFromDependents = Math.max(maxChainFromDependents, chainFromDependent);
    }
  }

  const result = cost + maxChainFromDependents;
  memo.set(task, result);
  return result;
}

function processPack(graph, workers) {
  const taskList = Array.from(graph.tasks.keys()).sort();

  if (taskList.length === 0) {
    // Empty graph
    for (let i = 0; i < workers; i++) {
      process.stdout.write(`worker ${i}:\n`);
    }
    process.stdout.write('makespan 0\n');
    return;
  }

  const workerQueues = Array(workers).fill(null).map(() => []);
  const taskStartTime = new Map();
  const taskFinishTime = new Map();
  const taskDone = new Set();

  const workerFreeAt = Array(workers).fill(0);
  let currentTime = 0;
  const priorityMemo = new Map();

  while (taskDone.size < taskList.length) {
    let assignedInThisRound = false;

    while (true) {
      // Find ready tasks
      const readyTasks = [];

      for (const task of taskList) {
        if (taskDone.has(task)) continue;

        const dependencies = graph.deps.get(task) || new Set();
        let canStart = true;

        for (const dep of dependencies) {
          if (!taskDone.has(dep)) {
            canStart = false;
            break;
          }
          // Check that dependency finished at or before current time
          if (taskFinishTime.get(dep) > currentTime) {
            canStart = false;
            break;
          }
        }

        if (canStart) {
          readyTasks.push(task);
        }
      }

      if (readyTasks.length === 0) break;

      // Sort by priority (descending), then by name (ascending)
      readyTasks.sort((a, b) => {
        const priorityA = computePriority(a, graph, priorityMemo);
        const priorityB = computePriority(b, graph, priorityMemo);

        if (priorityA !== priorityB) {
          return priorityB - priorityA;
        }

        return a.localeCompare(b);
      });

      // Try to assign a task
      let taskAssigned = false;
      for (const task of readyTasks) {
        // Find first free worker at currentTime
        for (let i = 0; i < workers; i++) {
          if (workerFreeAt[i] <= currentTime) {
            // Assign task
            const start = currentTime;
            const finish = start + graph.tasks.get(task);

            taskStartTime.set(task, start);
            taskFinishTime.set(task, finish);
            taskDone.add(task);

            workerQueues[i].push({ task, start, finish });
            workerFreeAt[i] = finish;

            taskAssigned = true;
            assignedInThisRound = true;
            break;
          }
        }

        if (taskAssigned) break;
      }

      if (!taskAssigned) break;
    }

    if (taskDone.size === taskList.length) break;

    // Advance time to next worker free time
    let nextTime = Infinity;
    for (let i = 0; i < workers; i++) {
      if (workerFreeAt[i] > currentTime) {
        nextTime = Math.min(nextTime, workerFreeAt[i]);
      }
    }

    if (nextTime === Infinity) {
      // This shouldn't happen, but break if it does
      break;
    }

    currentTime = nextTime;
  }

  // Print results
  let makespan = 0;
  for (let i = 0; i < workers; i++) {
    process.stdout.write(`worker ${i}:`);
    for (const { task, start, finish } of workerQueues[i]) {
      process.stdout.write(` ${task}@${start}-${finish}`);
      makespan = Math.max(makespan, finish);
    }
    process.stdout.write('\n');
  }

  process.stdout.write(`makespan ${makespan}\n`);
}

