{"file_path":"src/graph.js","content":"/**
 * Parsing and analysis of the build graph.
 *
 * A graph is `{ names, cost, deps }` where `names` lists the declared task
 * names in ascending order, `cost` maps a name to its cost and `deps` maps a
 * name to the ascending list of the names it depends on.
 */

const NAME = /^[A-Za-z0-9_.-]+$/
const UINT = /^[0-9]+$/

/** Ascending order on code units, which is what the report lines use. */
export function byName(a, b) {
  return a < b ? -1 : a > b ? 1 : 0
}

/** An error that carries the exit code the command must end with. */
export class GraphError extends Error {
  constructor(message, code) {
    super(message)
    this.code = code
  }
}

function fail(message) {
  return new GraphError(message, 2)
}

/**
 * Read the directives of the input into a graph, rejecting the first malformed
 * line and then the first dependency on a task no line declares.
 */
export function parse(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cost = new Map()
  const deps = new Map()
  const used = [] // every name a dep line names, in input order

  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue

    const words = line.split(/\s+/)
    const at = i + 1

    if (words[0] === 'task') {
      if (words.length !== 3) throw fail(`error: line ${at}: expected task <name> <cost>`)
      const [, name, text] = words
      if (!NAME.test(name)) throw fail(`error: line ${at}: invalid task name ${name}`)
      if (!UINT.test(text)) throw fail(`error: line ${at}: cost must be a non-negative integer`)
      if (cost.has(name)) throw fail(`error: line ${at}: task ${name} is declared twice`)
      cost.set(name, Number(text))
    } else if (words[0] === 'dep') {
      if (words.length < 3) throw fail(`error: line ${at}: expected dep <name> <dependency>...`)
      for (let w = 1; w < words.length; w += 1) {
        if (!NAME.test(words[w])) throw fail(`error: line ${at}: invalid task name ${words[w]}`)
      }
      const name = words[1]
      used.push(name)
      let set = deps.get(name)
      if (set === undefined) {
        set = new Set()
        deps.set(name, set)
      }
      for (let w = 2; w < words.length; w += 1) {
        used.push(words[w])
        set.add(words[w])
      }
    } else {
      throw fail(`error: line ${at}: unknown directive ${words[0]}`)
    }
  }

  for (const name of used) {
    if (!cost.has(name)) throw fail(`error: unknown task ${name}`)
  }

  const names = [...cost.keys()].sort(byName)
  const edges = new Map()
  for (const name of names) {
    const set = deps.get(name)
    edges.set(name, set === undefined ? [] : [...set].sort(byName))
  }

  return { names, cost, deps: edges }
}

/**
 * The first cycle a depth-first search finds, starting from each task in
 * ascending order and walking each task's dependencies in ascending order, or
 * null when the graph is acyclic. The names run from the task the search
 * re-entered back round to a repeat of it.
 */
export function findCycle(graph) {
  const state = new Map() // unset, 1 while on the path, 2 once finished
  const path = []

  for (const root of graph.names) {
    if (state.has(root)) continue
    const stack = [{ name: root, next: 0 }]
    state.set(root, 1)
    path.push(root)

    while (stack.length > 0) {
      const frame = stack[stack.length - 1]
      const edges = graph.deps.get(frame.name)
      if (frame.next < edges.length) {
        const dep = edges[frame.next]
        frame.next += 1
        const seen = state.get(dep)
        if (seen === 1) return path.slice(path.indexOf(dep)).concat(dep)
        if (seen === undefined) {
          state.set(dep, 1)
          path.push(dep)
          stack.push({ name: dep, next: 0 })
        }
      } else {
        state.set(frame.name, 2)
        path.pop()
        stack.pop()
      }
    }
  }

  return null
}

/** The names in an order where every task follows all of its dependencies. */
function topological(graph) {
  const order = []
  const seen = new Set()

  for (const root of graph.names) {
    if (seen.has(root)) continue
    seen.add(root)
    const stack = [{ name: root, next: 0 }]
    while (stack.length > 0) {
      const frame = stack[stack.length - 1]
      const edges = graph.deps.get(frame.name)
      if (frame.next < edges.length) {
        const dep = edges[frame.next]
        frame.next += 1
        if (!seen.has(dep)) {
          seen.add(dep)
          stack.push({ name: dep, next: 0 })
        }
      } else {
        order.push(frame.name)
        stack.pop()
      }
    }
  }

  return order
}

/**
 * The start, finish and depth of every task, and the makespan an unlimited
 * number of workers reaches.
 */
export function analyse(graph) {
  const order = topological(graph)
  const start = new Map()
  const finish = new Map()
  const depth = new Map()
  let total = 0

  for (const name of order) {
    let at = 0
    let level = 0
    const edges = graph.deps.get(name)
    for (const dep of edges) {
      if (finish.get(dep) > at) at = finish.get(dep)
      if (depth.get(dep) + 1 > level) level = depth.get(dep) + 1
    }
    const end = at + graph.cost.get(name)
    start.set(name, at)
    finish.set(name, end)
    depth.set(name, level)
    if (end > total) total = end
  }

  return { start, finish, depth, total }
}

/**
 * The priority of every task: the cost of the longest chain that begins at it,
 * its own cost plus the costs down to a task nothing depends on.
 */
export function priorities(graph) {
  const order = topological(graph)
  const priority = new Map()
  for (const name of graph.names) priority.set(name, graph.cost.get(name))

  for (let i = order.length - 1; i >= 0; i -= 1) {
    const name = order[i]
    const own = priority.get(name)
    for (const dep of graph.deps.get(name)) {
      const through = own + graph.cost.get(dep)
      if (through > priority.get(dep)) priority.set(dep, through)
    }
  }

  return priority
}

/**
 * Run the graph on a fixed number of workers, always starting the ready task
 * of greatest priority on the free worker of smallest index.
 */
export function pack(graph, workers) {
  const priority = priorities(graph)
  const dependents = new Map()
  const waiting = new Map()
  for (const name of graph.names) {
    dependents.set(name, [])
    waiting.set(name, graph.deps.get(name).length)
  }
  for (const name of graph.names) {
    for (const dep of graph.deps.get(name)) dependents.get(dep).push(name)
  }

  const runs = []
  for (let i = 0; i < workers; i += 1) runs.push([])
  const freeAt = new Array(workers).fill(0)

  const ready = []
  for (const name of graph.names) if (waiting.get(name) === 0) ready.push(name)

  const running = [] // tasks started but not yet released to their dependents
  let left = graph.names.length
  let now = 0
  let makespan = 0

  const better = (a, b) => {
    const pa = priority.get(a)
    const pb = priority.get(b)
    if (pa !== pb) return pa > pb
    return byName(a, b) < 0
  }

  while (left > 0) {
    for (;;) {
      // Release everything that has finished by now, freeing its dependents.
      let released = false
      for (let i = running.length - 1; i >= 0; i -= 1) {
        if (running[i].finish > now) continue
        const done = running[i].name
        running.splice(i, 1)
        released = true
        for (const next of dependents.get(done)) {
          waiting.set(next, waiting.get(next) - 1)
          if (waiting.get(next) === 0) ready.push(next)
        }
      }

      // Start what can start on the free workers.
      let started = false
      for (;;) {
        if (ready.length === 0) break
        let worker = -1
        for (let i = 0; i < workers; i += 1) {
          if (freeAt[i] <= now) {
            worker = i
            break
          }
        }
        if (worker === -1) break

        let pick = 0
        for (let i = 1; i < ready.length; i += 1) if (better(ready[i], ready[pick])) pick = i
        const name = ready.splice(pick, 1)[0]

        const finish = now + graph.cost.get(name)
        runs[worker].push({ name, start: now, finish })
        freeAt[worker] = finish
        running.push({ name, finish })
        left -= 1
        started = true
        if (finish > makespan) makespan = finish
      }

      if (!released && !started) break
    }

    if (left === 0) break

    // Nothing more can start now, so wait for the next worker to come free.
    let next = Infinity
    for (let i = 0; i < workers; i += 1) if (freeAt[i] > now && freeAt[i] < next) next = freeAt[i]
    for (const task of running) if (task.finish > now && task.finish < next) next = task.finish
    if (next === Infinity) break
    now = next
  }

  return { runs, makespan }
}
"}

