  let now = 0
  let makespan = 0

  const better = (a, b) => {
    const pa = priority.get(a)
    const pb = priority.get(b)
    if (pa !== pb) return pa > pb
    return byName(a, b) < 0
  }

  while (left > 0) {
    for (;;) {
      // Release everything that has finished by now, freeing its dependents.
      let released = false
      for (let i = running.length - 1; i >= 0; i -= 1) {
        if (running[i].finish > now) continue
        const done = running[i].name
        running.splice(i, 1)
        released = true
        for (const next of dependents.get(done)) {
          waiting.set(next, waiting.get(next) - 1)
          if (waiting.get(next) === 0) ready.push(next)
        }
      }

      // Start what can start on the free workers.
      let started = false
      for (;;) {
        if (ready.length === 0) break
        let worker = -1
        for (let i = 0; i < workers; i += 1) {
          if (freeAt[i] <= now) {
            worker = i
            break
          }
        }
        if (worker === -1) break

        let pick = 0
        for (let i = 1; i < ready.length; i += 1) if (better(ready[i], ready[pick])) pick = i
        const name = ready.splice(pick, 1)[0]

        const finish = now + graph.cost.get(name)
        runs[worker].push({ name, start: now, finish })
        freeAt[worker] = finish
        running.push({ name, finish })
        left -= 1
        started = true
        if (finish > makespan) makespan = finish
      }

      if (!released && !started) break
    }

    if (left === 0) break

    // Nothing more can start now, so wait for the next worker to come free.
    let next = Infinity
    for (let i = 0; i < workers; i += 1) if (freeAt[i] > now && freeAt[i] < next) next = freeAt[i]
    for (const task of running) if (task.finish > now && task.finish < next) next = task.finish
    if (next === Infinity) break
    now = next
  }

  return { runs, makespan }
}
