import { readFileSync } from 'node:fs'
import { GraphError, analyse, findCycle, pack, parse } from './graph.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'

/** The mode and worker count the arguments ask for, or a usage failure. */
function readArguments(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0], workers: 0 }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!/^[1-9][0-9]*$/.test(argv[1])) {
      throw new GraphError('error: workers must be a positive integer', 2)
    }
    return { mode: 'pack', workers: Number(argv[1]) }
  }
  throw new GraphError(USAGE, 2)
}

function readInput() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

/** The `waves` report: the tasks by depth, then the unlimited makespan. */
function waves(graph) {
  const { depth, total } = analyse(graph)
  const groups = []
  for (const name of graph.names) {
    const level = depth.get(name)
    while (groups.length <= level) groups.push([])
    groups[level].push(name)
  }
  const lines = groups.map((group, level) => `wave ${level}: ${group.join(' ')}\n`)
  return lines.join('') + `total ${total}\n`
}

/** The `explain` report: one line per task, then the unlimited makespan. */
function explain(graph) {
  const { start, finish, depth, total } = analyse(graph)
  let out = ''
  for (const name of graph.names) {
    out += `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}\n`
  }
  return out + `total ${total}\n`
}

/** The `pack` report: what each worker ran, then the makespan it reached. */
function schedule(graph, workers) {
  const { runs, makespan } = pack(graph, workers)
  let out = ''
  for (let i = 0; i < runs.length; i += 1) {
    out += `worker ${i}:`
    for (const run of runs[i]) out += ` ${run.name}@${run.start}-${run.finish}`
    out += '\n'
  }
  return out + `makespan ${makespan}\n`
}

function main() {
  const { mode, workers } = readArguments(process.argv.slice(2))
  const graph = parse(readInput())

  const cycle = findCycle(graph)
  if (cycle !== null) throw new GraphError(`error: cycle: ${cycle.join(' -> ')}`, 3)

  if (mode === 'waves') return waves(graph)
  if (mode === 'explain') return explain(graph)
  return schedule(graph, workers)
}

try {
  process.stdout.write(main())
} catch (error) {
  if (error instanceof GraphError) {
    process.stderr.write(`${error.message}\n`)
    process.exitCode = error.code
  } else {
    throw error
  }
}

