  const n = 1 + Math.floor(rnd() * 7)
  const names = []
  for (let i = 0; i < n; i++) names.push(String.fromCharCode(97 + i))
  const lines = names.map((x) => `task ${x} ${Math.floor(rnd() * 4)}`)
  for (let i = 0; i < n; i++) for (let j = 0; j < i; j++) if (rnd() < 0.35) lines.push(`dep ${names[i]} ${names[j]}`)
  const inp = lines.join('\n') + '\n'
  const w = 1 + Math.floor(rnd() * 3)
  const a = execFileSync('node', ['src/cli.js', 'pack', String(w)], { input: inp, encoding: 'utf8' })
  const b = execFileSync('node', ['ref/ref.mjs', String(w)], { input: inp, encoding: 'utf8' })
  if (a !== b) { console.log('MISMATCH w=' + w + '\n' + inp + '--mine--\n' + a + '--ref--\n' + b); break }
}
console.log('done')
